use crate::{
    constants::DOM_SEP__PUBLIC_STORAGE_MAP_SLOT, hash::poseidon2_hash_with_separator,
    traits::ToField,
};

// TODO: Move this to src/public_data/storage/map.nr
pub fn derive_storage_slot_in_map<K>(storage_slot: Field, key: K) -> Field
where
    K: ToField,
{
    poseidon2_hash_with_separator(
        [storage_slot, key.to_field()],
        DOM_SEP__PUBLIC_STORAGE_MAP_SLOT,
    )
}

mod test {
    use crate::{address::AztecAddress, storage::map::derive_storage_slot_in_map, traits::FromField};

