fn wrapping_add_hlp<T>(x: T, y: T) -> T
where
    T: AsPrimitive<Field>,
    Field: AsPrimitive<T>,
{
    AsPrimitive::as_(x.as_() + y.as_())
}

fn wrapping_sub_hlp<T>(x: T, y: T) -> Field
where
    T: AsPrimitive<Field>,
{
    //340282366920938463463374607431768211456 is 2^128, it is used to avoid underflow
    x.as_() + 340282366920938463463374607431768211456 - y.as_()
}

fn wrapping_mul_hlp<T>(x: T, y: T) -> T
where
    T: AsPrimitive<Field>,
    Field: AsPrimitive<T>,
{
    AsPrimitive::as_(x.as_() * y.as_())
}

global two_pow_64: u128 = 0x10000000000000000;
/// Splits a 128 bits number into two 64 bits limbs
unconstrained fn split64(x: u128) -> (u64, u64) {
    let lo = x as u64;
    let hi = (x / two_pow_64) as u64;
    (lo, hi)
}

/// Split a 128 bits number into two 64 bits limbs
/// It will fail if the number is more than 128 bits
fn split_into_64_bit_limbs(x: u128) -> (u64, u64) {
    // Safety: the limbs are constrained below
    let (x_lo, x_hi) = unsafe { split64(x) };
    assert(x as Field == x_lo as Field + x_hi as Field * two_pow_64 as Field);
    (x_lo, x_hi)
}

#[field(bn254)]
fn wrapping_mul128_hlp(x: u128, y: u128) -> u128 {
    let (x_lo, x_hi) = split_into_64_bit_limbs(x);
    let (y_lo, y_hi) = split_into_64_bit_limbs(y);
    // Multiplication using the limbs:(x_lo + 2**64*x_hi)*(y_lo + 2**64*y_hi)=x_lo*y_lo+...
    // and skipping the terms over 2**128
    // Working with u64 limbs ensures that we cannot overflow the field modulus.
    let low = x_lo as Field * y_lo as Field;
    let lo = low as u64 as Field;
    let carry = (low - lo) / two_pow_64 as Field;
    let high = x_lo as Field * y_hi as Field + x_hi as Field * y_lo as Field + carry;
    let hi = high as u64 as Field;
    (lo + two_pow_64 as Field * hi) as u128
}

mod tests {
    #[test(should_fail_with = "custom message")]
    fn test_static_assert_custom_message() {
        crate::static_assert(1 == 2, "custom message");
    }

    mod arithmetic {
        use crate::ops::arith::{Add, Div, Mul, Neg, Rem, Sub};
        #[test]
        fn test_basic_arithmetic_traits() {
            // add
            assert_eq(5.add(3), 8);
            assert_eq(0u8.add(255u8), 255u8);
            assert_eq(42.add(58), 100);

            // sub
            assert_eq(10.sub(3), 7);
            assert_eq(100.sub(42), 58);

            // mul
            assert_eq(6.mul(7), 42);

            // div
            assert_eq(15.div(3), 5);
            assert_eq(10u8.div(3u8), 3u8);
            assert_eq(15.div(3), 5);

            // rem (Field doesn't implement Rem)
            assert_eq(17u64.rem(5u64), 2u64);
            assert_eq(10u8.rem(3u8), 1u8);

            // neg
            assert_eq(42.neg(), -42);
            assert_eq((-10).neg(), 10);
            assert_eq(42.neg(), -42);
        }

        #[test]
        fn test_division() {
            // test division by one
            assert_eq(42.div(1), 42);
            assert_eq(0.div(1), 0);
            assert_eq(255u8.div(1u8), 255u8);

            // test division by self
            assert_eq(42.div(42), 1);
            assert_eq(1.div(1), 1);

            // test remainder (Field doesn't implement Rem)
            assert_eq(42u32.rem(42u32), 0u32);
            assert_eq(0u16.rem(42u16), 0u16);
            assert_eq(1u64.rem(42u64), 1u64);
        }

        // Per-operator overflow corners. The signed `iN::MIN` corners pin down
        // compiler-side overflow detection on the trait dispatch path: the
        // trait impls are one-line delegations to the built-in operators and
        // rely entirely on the compiler's lowering to emit the two's-complement
        // overflow constraints. These tests trip CI on any future SSA pass
        // that drops one of those constraints.
        //
        // Each case pins the exact runtime message via `should_fail_with`, so a
        // regression that starts failing for the *wrong* reason (a divide by
        // zero, or a panic in unrelated code) is caught too, rather than being
        // accepted as "it failed somehow". The matcher is a case-insensitive
        // substring, so the same string works under both ACIR and Brillig even
        // though Brillig capitalizes the divide/remainder messages.

        mod add {
            use crate::ops::arith::Add;

            // `MAX + 1` is one past the largest representable value, so the
            // range check on the sum rejects it. For unsigned this is a wrap
            // past `2^bits - 1`; for signed it steps out of `[MIN, MAX]`.

            #[test(should_fail_with = "attempt to add with overflow")]
            fn u8_overflow() {
                let _ = 255u8.add(1u8);
            }

            #[test(should_fail_with = "attempt to add with overflow")]
            fn u16_overflow() {
                let _ = 65535u16.add(1u16);
            }

            #[test(should_fail_with = "attempt to add with overflow")]
            fn i8_overflow() {
                let _ = 127i8.add(1i8);
            }

            #[test(should_fail_with = "attempt to add with overflow")]
            fn i16_overflow() {
                let _ = 32767i16.add(1i16);
            }

            #[test(should_fail_with = "attempt to add with overflow")]
            fn i32_overflow() {
                let _ = 2147483647i32.add(1i32);
            }

            #[test(should_fail_with = "attempt to add with overflow")]
            fn i64_overflow() {
                let _ = 9223372036854775807i64.add(1i64);
            }
        }

        mod sub {
            use crate::ops::arith::Sub;

            // Subtraction underflows past the type's minimum: `0 - 1` for
            // unsigned (a borrow below zero), and `MIN - 1` for signed (one step
            // below the most-negative value).

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn u8_overflow() {
                let _ = 0u8.sub(1u8);
            }

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn u16_overflow() {
                let _ = 0u16.sub(1u16);
            }

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn i8_overflow() {
                let val: i8 = -128;
                let _ = val.sub(1i8);
            }

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn i16_overflow() {
                let val: i16 = -32768;
                let _ = val.sub(1i16);
            }

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn i32_overflow() {
                let val: i32 = -2147483648;
                let _ = val.sub(1i32);
            }

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn i64_overflow() {
                let val: i64 = -9223372036854775808;
                let _ = val.sub(1i64);
            }
        }

        mod mul {
            use crate::ops::arith::Mul;

            // Unsigned `MAX * 2` exceeds the maximum. The signed corner is
            // `MIN * -1`: the true product is `-MIN == 2^(bits-1)`, exactly one
            // past the signed maximum `2^(bits-1) - 1`, so it is unrepresentable.
            // This is the same range asymmetry that makes negating MIN overflow.

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn u8_overflow() {
                let _ = 255u8.mul(2u8);
            }

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn u16_overflow() {
                let _ = 65535u16.mul(2u16);
            }

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn i8_min_times_neg_one_overflow() {
                let val: i8 = -128;
                let _ = val.mul(-1i8);
            }

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn i16_min_times_neg_one_overflow() {
                let val: i16 = -32768;
                let _ = val.mul(-1i16);
            }

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn i32_min_times_neg_one_overflow() {
                let val: i32 = -2147483648;
                let _ = val.mul(-1i32);
            }

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn i64_min_times_neg_one_overflow() {
                let val: i64 = -9223372036854775808;
                let _ = val.mul(-1i64);
            }
        }

        mod div {
            use crate::ops::arith::Div;

            // `MIN / -1` is the only division that overflows: the quotient is
            // `-MIN == 2^(bits-1)`, one past the signed maximum. (Division by
            // zero is a distinct error and is not what these cases exercise.)

            #[test(should_fail_with = "attempt to divide with overflow")]
            fn i8_min_by_neg_one_overflow() {
                let val: i8 = -128;
                let _ = val.div(-1i8);
            }

            #[test(should_fail_with = "attempt to divide with overflow")]
            fn i16_min_by_neg_one_overflow() {
                let val: i16 = -32768;
                let _ = val.div(-1i16);
            }

            #[test(should_fail_with = "attempt to divide with overflow")]
            fn i32_min_by_neg_one_overflow() {
                let val: i32 = -2147483648;
                let _ = val.div(-1i32);
            }

            #[test(should_fail_with = "attempt to divide with overflow")]
            fn i64_min_by_neg_one_overflow() {
                let val: i64 = -9223372036854775808;
                let _ = val.div(-1i64);
            }
        }

        mod rem {
            use crate::ops::arith::Rem;

            // `MIN % -1` is mathematically 0, but it is computed via the same
            // `MIN / -1` division that overflows, so the operation is rejected
            // rather than silently yielding 0. This matches Rust, where
            // `iN::MIN % -1` also overflows.

            #[test(should_fail_with = "attempt to calculate the remainder with overflow")]
            fn i8_min_by_neg_one_overflow() {
                let val: i8 = -128;
                let _ = val.rem(-1i8);
            }

            #[test(should_fail_with = "attempt to calculate the remainder with overflow")]
            fn i16_min_by_neg_one_overflow() {
                let val: i16 = -32768;
                let _ = val.rem(-1i16);
            }

            #[test(should_fail_with = "attempt to calculate the remainder with overflow")]
            fn i32_min_by_neg_one_overflow() {
                let val: i32 = -2147483648;
                let _ = val.rem(-1i32);
            }

            #[test(should_fail_with = "attempt to calculate the remainder with overflow")]
            fn i64_min_by_neg_one_overflow() {
                let val: i64 = -9223372036854775808;
                let _ = val.rem(-1i64);
            }
        }

        mod neg {
            use crate::ops::arith::Neg;

            // Negating `MIN` overflows because the two's-complement range is
            // asymmetric: `-MIN == 2^(bits-1)` has no representable positive
            // counterpart (the maximum is only `2^(bits-1) - 1`). MIN is the
            // unique value with this property, so it is the only negation that
            // fails. The wording of the failure depends on the execution path:
            // the comptime interpreter reports "attempt to negate with
            // overflow", while ACIR/Brillig lower unary `-` to `0 - x` and so
            // report "attempt to subtract with overflow". Both share
            // "with overflow", which is what these cases assert on.

            #[test(should_fail_with = "with overflow")]
            fn i8_min_overflow() {
                let val: i8 = -128;
                let _ = val.neg();
            }

            #[test(should_fail_with = "with overflow")]
            fn i16_min_overflow() {
                let val: i16 = -32768;
                let _ = val.neg();
            }

            #[test(should_fail_with = "with overflow")]
            fn i32_min_overflow() {
                let val: i32 = -2147483648;
                let _ = val.neg();
            }

            #[test(should_fail_with = "with overflow")]
            fn i64_min_overflow() {
                let val: i64 = -9223372036854775808;
                let _ = val.neg();
            }
        }

