            assert_eq(one.add(zero), one);
            assert_eq(one.sub(one), zero);
            assert_eq(one.mul(one), one);
            assert_eq(one.div(one), one);
            assert_eq(zero.neg(), zero);
            assert_eq(one.neg(), -one);
